.premium-pricing-container {
  display: flex;
  justify-content: center;
  align-items: stretch;
  gap: 28px;
  max-width: 1440px;
  margin: 20px auto;
  font-family: 'Raleway', sans-serif;
  box-sizing: border-box;
  padding: 0 20px;
}

/* Premium Card Layout */
.premium-card {
  flex: 1;
  background: #ffffff;
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.04);
  border: 1px solid rgba(0, 0, 0, 0.06);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.3s ease;
  overflow: hidden;
  position: relative;
}

.premium-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08);
}

.premium-card.popular {
  border: 2px solid #518cb8;
  transform: scale(1.02);
}
.premium-card.popular:hover {
  transform: scale(1.02) translateY(-6px);
}

/* Side-by-side Compressed Header Design */
.card-header {
  padding: 24px 20px;
  color: #ffffff;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
}
.basic .card-header { background: linear-gradient(135deg, #79c96a, #67b758); }
.advanced .card-header { background: linear-gradient(135deg, #518cb8, #3f7aa6); }
.premium .card-header { background: linear-gradient(135deg, #dc5667, #c94354); }

.header-left {
  text-align: left;
  flex: 1;
}

.duration-badge {
  display: inline-block;
  font-size: 12px;
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 6px;
  background: rgba(255, 255, 255, 0.2);
  padding: 3px 10px;
  border-radius: 20px;
}

.card-header h2 {
  font-size: 27px;
  font-weight: 800;
  margin: 0 0 4px 0;
  letter-spacing: -0.5px;
  color: #ffffff !important;
  line-height: 1.2;
}

.subtitle {
  font-size: 15px;
  line-height: 1.4;
  margin: 0;
  opacity: 0.9;
  font-weight: 400;
}

.price {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -1px;
  white-space: nowrap;
  text-align: right;
}

.price-period {
  font-size: 13px;
  font-weight: 500;
  opacity: 0.8;
}

/* Feature Matrix List Custom Styling */
.card-features {
  padding: 25px 22px;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  background-color: #ffffff;
}

.card-features ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.card-features li {
  font-size: 15px;
  font-weight: 500;
  color: #4a5568;
  padding: 8px 0;
  line-height: 1.5;
  position: relative;
  padding-left: 26px;
  border-bottom: 1px solid #f7fafc;
}
.card-features li:last-child {
  border-bottom: none;
}

/* Base Checkmarks and Crosses */
.card-features li.included::before {
  content: "✓";
  position: absolute;
  left: 2px;
  font-weight: 700;
  font-size: 14px;
  color: #79c96a;
}
.card-features li.excluded {
  color: #a0aec0;
}
.card-features li.excluded::before {
  content: "×";
  position: absolute;
  left: 4px;
  color: #e53e3e;
  font-weight: 700;
  font-size: 16px;
  top: 6px;
}

/* --- New Rules: Targeted Highlight Sections From Screenshot --- */

/* Basic Highlights */
.card-features li.basic-highlight {
  font-weight: 700;
  color: #2ea117;
}
.card-features li.basic-highlight.excluded {
  color: #2ea117; 
}
.card-features li.basic-highlight.excluded::before {
  content: "×";
  color: #2ea117;
}
.card-features li.basic-highlight.included::before {
  color: #2ea117;
}

/* Advanced Highlights */
.card-features li.advanced-highlight {
  font-weight: 700;
  color: #1d72b8;
}
.card-features li.advanced-highlight::before {
  color: #1d72b8 !important;
}

/* Premium Highlights */
.card-features li.premium-highlight {
  font-weight: 700;
  color: #d13b4f;
}
.card-features li.premium-highlight::before {
  color: #d13b4f !important;
}

/* Clean, Premium Footers with Integrated Dropdowns */
.card-footer {
  padding: 25px;
  border-top: 1px solid rgba(0, 0, 0, 0.04);
}
.basic .card-footer { background-color: #f4fbf3; }
.advanced .card-footer { background-color: #f3f7fa; }
.premium .card-footer { background-color: #fdf5f6; }

.card-footer label {
  display: block;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #4a5568;
  margin-bottom: 8px;
}

/* Dropdown styling wrappers */
.select-wrapper {
  position: relative;
  width: 100%;
}

.select-wrapper::after {
  content: "▼";
  font-size: 10px;
  color: #718096;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  position: absolute;
  pointer-events: none;
}

.card-footer select {
  width: 100%;
  font-family: 'Raleway', sans-serif;
  padding: 12px 34px 12px 14px;
  font-size: 13px;
  font-weight: 600;
  color: #2d3748;
