}

.card-footer select:hover {
  border-color: #cbd5e0;
}

.card-footer select:focus {
  border-color: #4a5568;
  box-shadow: 0 0 0 3px rgba(66, 153, 225, 0.15);
}

/* Tablet & Mobile Layout Fallbacks */
@media (max-width: 992px) {
